//
// Generates string-width-table.zig: the width that the `string-width` package (v7.2.0) gives each
// single code point, as sorted ranges of the code points whose width is 0 or 2 (all others are 1).
// Run from the repo root: bun run apps/cli-zig/src/lib/clack/third-party/generate-string-width-table.ts
//
import stringWidth from "string-width";
import { writeFileSync } from "fs";
import { join } from "path";

//
// A range of code points that share a width.
//
interface IWidthRange {
    // First code point of the range.
    start: number;

    // Last code point of the range.
    end: number;

    // The width of every code point in the range.
    width: number;
}

const ranges: IWidthRange[] = [];
for (let codePoint = 0; codePoint <= 0x10FFFF; codePoint++) {
    if (codePoint >= 0xD800 && codePoint <= 0xDFFF) {
        continue;
    }
    const width = stringWidth(String.fromCodePoint(codePoint));
    if (width === 1) {
        continue;
    }
    const last = ranges[ranges.length - 1];
    if (last && last.width === width && last.end === codePoint - 1) {
        last.end = codePoint;
    }
    else {
        ranges.push({ start: codePoint, end: codePoint, width });
    }
}

const lines: string[] = [];
lines.push("//");
lines.push("// Generated by generate-string-width-table.ts from the `string-width` package (v7.2.0). Do not edit.");
lines.push("// The code points whose width is not 1, as sorted ranges (surrogates excluded).");
lines.push("//");
lines.push("");
lines.push("//");
lines.push("// A range of code points that share a width.");
lines.push("//");
lines.push("pub const WidthRange = struct {");
lines.push("    // First code point of the range.");
lines.push("    start: u21,");
lines.push("");
lines.push("    // Last code point of the range.");
lines.push("    end: u21,");
lines.push("");
lines.push("    // The width of every code point in the range (0 or 2).");
lines.push("    width: u2,");
lines.push("};");
lines.push("");
lines.push("//");
lines.push("// The ranges, sorted by start.");
lines.push("//");
lines.push("pub const ranges = [_]WidthRange{");
for (const range of ranges) {
    lines.push(`    .{ .start = 0x${range.start.toString(16).toUpperCase()}, .end = 0x${range.end.toString(16).toUpperCase()}, .width = ${range.width} },`);
}
lines.push("};");
lines.push("");
writeFileSync(join(import.meta.dir, "string-width-table.zig"), lines.join("\n"));
console.log(`${ranges.length} ranges`);
